# leftovers.sh -- inside a machine after --uninstall: what FrogNet left, and whether names resolve
echo "units: $(ls /etc/systemd/system /lib/systemd/system 2>/dev/null | grep -E '^(frognet|fdf)-' | sort -u | tr '\n' ' ')"
echo "loaded: $(systemctl list-units --all --plain --no-legend 'frognet-*' 'fdf-*' 2>/dev/null | awk '{print $1}' | tr '\n' ' ')"
echo "crontab: $(crontab -l 2>&1 | tr '\n' ';')"
echo "froguser: $(id froguser 2>&1)"
echo "hooks: $(ls /etc/NetworkManager/dispatcher.d/ | tr '\n' ' ')  conf.d: $(ls /etc/NetworkManager/conf.d/ 2>/dev/null | tr '\n' ' ')"
echo "dirs: $(for d in /opt/frognet_semantic /opt/fdf /etc/frognet /etc/sentinels /var/www/html /usr/local/bin/installer /usr/local/lib/frognet /var/lib/frognet-install /var/lib/frognet-tunnel /etc/fnid; do [ -e $d ] && echo -n "$d "; done)"
echo "/usr/local/bin: $(ls /usr/local/bin | wc -l) entries: $(ls /usr/local/bin | head -8 | tr '\n' ' ')"
echo "/usr/local/sbin: $(ls /usr/local/sbin | wc -l)  /usr/local/lib: $(ls /usr/local/lib | tr '\n' ' ')"
echo "etc files: $(ls /etc/sysctl.d/*frognet* /etc/dnsmasq.d/* /etc/apache2/sites-enabled/* /etc/logrotate.d/frognet /etc/sudoers.d/frognet* /etc/mysql/mariadb.conf.d/*frognet* /etc/ssl/frognet* 2>/dev/null | tr '\n' ' ')"
echo "services: $(for u in dnsmasq apache2 mariadb NetworkManager systemd-resolved; do echo -n "$u=$(systemctl is-enabled $u 2>/dev/null)/$(systemctl is-active $u 2>/dev/null) "; done)"
echo "resolv.conf: $(grep -v '^#' /etc/resolv.conf | grep . | tr '\n' ' ')"
echo "getent hosts archive.ubuntu.com: $(getent hosts archive.ubuntu.com | head -1)"
echo "hostname: $(hostname) / $(cat /etc/hostname)"
